package io.aegis
import kotlin.test.*
import java.math.BigDecimal
import kotlinx.coroutines.test.runTest
class CoreTest{@Test fun progressionAndIndependence(){val a=Progression(PanelConfig(BigDecimal.ONE),Progress(BigDecimal.ONE));val b=Progression(PanelConfig(BigDecimal.TEN),Progress(BigDecimal.TEN));listOf("10.00","100.00","1000.00").forEach{assertEquals(it,a.apply(Outcome.LOSS).stake.toPlainString())};b.apply(Outcome.LOSS);b.apply(Outcome.WIN);assertEquals("10.00",b.state.stake.toPlainString());assertEquals("1000.00",a.state.stake.toPlainString())};@Test fun unknownNeverProgresses(){val a=Progression(PanelConfig(BigDecimal.ONE),Progress(BigDecimal.ONE));a.apply(Outcome.UNKNOWN);assertEquals(0,a.state.level)};@Test fun balanceNeverOutcome(){assertEquals(Outcome.UNKNOWN,OutcomeResolver.resolve(null,null,null,null,null,null,true))};@Test fun realSafeguards(){val g=EnvGuard();assertEquals(Env.DEMO,g.env);assertFails{g.select(Env.REAL)};g.select(Env.REAL,"I UNDERSTAND THE RISKS");assertFalse(g.mayAct());g.start(true);assertTrue(g.mayAct());g.restart();assertFalse(g.mayAct())};@Test fun duplicateProtected()=runTest{val x=ActionLocks();var n=0;assertTrue(x.submit("r",Panel.P1,{true}){n++;true});assertFalse(x.submit("r",Panel.P1,{true}){n++;true});assertTrue(x.submit("r",Panel.P2,{true}){n++;true});assertEquals(2,n)};@Test fun watchdog(){assertTrue(Watchdog(10).paused(11,0,true,false,0,3));assertTrue(Watchdog().paused(1,0,true,true,0,3))}}
